Shader "Hidden/ProBuilder/FaceHighlight"
{
    Properties
    {
        _Color ("Color Tint", Color) = (1,1,1,1)
        _Dither ("Dithering", float) = 0
        _HandleZTest ("_HandleZTest", Int) = 8
        _HandleZWrite("_HandleZWrite", Int) = 0
    }

    SubShader
    {
        Tags { "IgnoreProjector"="True" "Queue"="Transparent" }
        Lighting Off
        ZTest [_HandleZTest]
        ZWrite [_HandleZWrite]
        Cull Off
        Blend SrcAlpha OneMinusSrcAlpha

        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "UnityCG.cginc"
            #include "ProBuilderCG.cginc"

            float4 _Color;
            float _Dither;

            struct appdata

            struct v2f
            {
                float4 pos : SV_POSITION;
            };

            v2f vert (appdata v)
            {
                v2f o;
				o.pos = UnityObjectToClipPosWithOffset(v.vertex.xyz);
                return o;
            }

            half4 frag (v2f i) : SV_Target
            {
                i.pos.xy = floor(i.pos.xy * 1) * .5;
                float checker = -frac(i.pos.x + i.pos.y);
                clip(lerp(1, checker, _Dither));

                return _Color;
            }

            ENDCG

v2f vert (appdata v)
{
    v2f o;

    o.pos = float4(UnityObjectToViewPos(v.vertex.xyz), 1);

    // pull closer to camera and into clip space
    o.pos *= .99;
    o.pos = mul(UNITY_MATRIX_P, o.pos);
    // convert clip -> ndc -> screen, build billboards in geo shader, then screen -> ndc -> clip
    o.pos = ClipToScreen(o.pos);
    o.color = v.color;
    return o;
}

[maxvertexcount(4)]
void geo(line v2f p[2], inout TriangleStream<v2f> triStream)
{
    float2 perp = normalize(float2(-(p[1].pos.y - p[0].pos.y), p[1].pos.x - p[0].pos.x)) * _Scale;

    v2f geo_out;

    geo_out.pos = ScreenToClip( float4(p[1].pos.x + perp.x, p[1].pos.y + perp.y, p[1].pos.z, p[1].pos.w) );
    geo_out.color = p[1].color;
    triStream.Append(geo_out);

    geo_out.pos =  ScreenToClip( float4(p[1].pos.x - perp.x, p[1].pos.y - perp.y, p[1].pos.z, p[1].pos.w) );
    geo_out.color = p[1].color;
    triStream.Append(geo_out);

    geo_out.pos =  ScreenToClip( float4(p[0].pos.x + perp.x, p[0].pos.y + perp.y, p[0].pos.z, p[0].pos.w) );
    geo_out.color = p[0].color;
    triStream.Append(geo_out);

    geo_out.pos =  ScreenToClip( float4(p[0].pos.x - perp.x, p[0].pos.y - perp.y, p[0].pos.z, p[0].pos.w) );
    geo_out.color = p[0].color;
    triStream.Append(geo_out);
}

v2f vert (appdata v)
{
    v2f o;

    o.pos = UnityObjectToClipPosWithOffsetMetal(v.vertex.xyz);

    // convert vertex to screen space, add pixel-unit xy to vertex, then transform back to clip space.
    float4 clip = o.pos;

    float4 a = ClipToScreen(o.pos);
    float4 b = ClipToScreen(UnityObjectToClipPosWithOffset(v.tangent.xyz));
    float2 d = normalize(b-a).xy;
    float2 p = float2(-d.y, d.x);
    a.xy += p * v.tangent.w * _Scale;

    o.pos = ScreenToClip(a);
    return o;
}

GS_INPUT vert(appdata v)
{
    GS_INPUT output = (GS_INPUT)0;

    output.pos = float4(UnityObjectToViewPos(v.vertex.xyz), 1);
    // perspective rendering applies offset in view coordinates, and orthographic applies offset in the geometry
    // shader screen space
    output.pos.xyz *= lerp(1, .95, ORTHO);
    output.pos = mul(UNITY_MATRIX_P, output.pos);
    // convert clip -> ndc -> screen, build billboards in geo shader, then screen -> ndc -> clip
    output.pos = ClipToScreen(output.pos);
    output.color = v.color;

    return output;
}

[maxvertexcount(4)]
void geo(point GS_INPUT p[1], inout TriangleStream<FS_INPUT> triStream)
{
    // 3  1
    // 2  0

    FS_INPUT geo_out;
    geo_out.color = p[0].color;

    geo_out.pos = ScreenToClip( float4(p[0].pos.x + _Scale, p[0].pos.y - _Scale, p[0].pos.z, p[0].pos.w - ScreenDepthModifier) );
    triStream.Append(geo_out);

    geo_out.pos =  ScreenToClip( float4(p[0].pos.x + _Scale, p[0].pos.y + _Scale, p[0].pos.z, p[0].pos.w - ScreenDepthModifier) );
    triStream.Append(geo_out);

    geo_out.pos =  ScreenToClip( float4(p[0].pos.x - _Scale, p[0].pos.y - _Scale, p[0].pos.z, p[0].pos.w - ScreenDepthModifier) );
    triStream.Append(geo_out);

    geo_out.pos =  ScreenToClip( float4(p[0].pos.x - _Scale, p[0].pos.y + _Scale, p[0].pos.z, p[0].pos.w - ScreenDepthModifier) );
    triStream.Append(geo_out);
}

v2f vert (appdata v)
{
    float ortho = (1 - UNITY_MATRIX_P[3][3]);
    v2f o;

    o.pos = float4(UnityObjectToViewPos(v.vertex.xyz), 1);
    o.pos.xyz *= lerp(.99, .95, ortho);
    o.pos = mul(UNITY_MATRIX_P, o.pos);

    // convert vertex to screen space, add pixel-unit xy to vertex, then transform back to clip space.
    float4 clip = o.pos;

    clip.xy /= clip.w;
    clip.xy = clip.xy * .5 + .5;
    clip.xy *= _ScreenParams.xy;

    clip.xy += v.texcoord.xy * _Scale;
    clip.xy /= _ScreenParams.xy;
    clip.xy = (clip.xy - .5) / .5;
    clip.xy *= clip.w;

    o.pos = clip;

    return o;
}

